class Solution {
public:
    vector<long long> minimumCosts(vector<int>& regular, vector<int>& express, int expressCost) {
        long long r = 0, e = expressCost;
        vector<long long> answer;
        for (int i = 0; i < (int)regular.size(); ++i) {
            long long nr = min(r, e) + regular[i];
            long long ne = min(e, r + expressCost) + express[i];
            r = nr; e = ne;
            answer.push_back(min(r, e));
        }
        return answer;
    }
};
